'use strict';
const AGENTS = {
  SENTINEL: { name: 'Threat Detection', in: 'Normalised security events (auth, app, system, network, API, file, cloud)', out: 'Alert JSON: category, risk 0–100, severity, evidence IDs, affected entities, recommended action, MITRE hints', tools: '20+ detection rules · z-score anomaly model · sliding windows', perm: 'READ events only. Cannot act on any system.' },
  INVESTIGATOR: { name: 'Threat Investigation', in: 'Correlated alerts + event store', out: 'Investigation JSON: timeline, attack graph, confirmed findings vs hypotheses, techniques (evidence-supported / hypothesis), confidence', tools: 'Event correlation · graph builder · static email analysis (URLs never opened) · optional LLM prose', perm: 'READ only. LLM output can never alter structured facts.' },
  ORACLE: { name: 'Threat Intelligence', in: 'IPs, domains, file hashes from the incident', out: 'Intel JSON: verdict (malicious / suspicious / no_detections / unknown), source, tags', tools: 'VirusTotal v3 API → local sample DB fallback', perm: 'Outbound reputation lookups only. Unknown ≠ malicious.' },
  GUARDIAN: { name: 'Automated Containment', in: 'Investigation + intel', out: 'Plan JSON: actions tagged AUTOMATIC / APPROVAL / RESTRICTED + manual-only list', tools: 'Whitelisted functions: block_ip, revoke_sessions, revoke_token, restrict_resource, disable_account, isolate_host, cloud policy/bucket fixes', perm: 'Policy engine re-checks every action at execution. RESTRICTED actions can never run. No shell, no eval.' },
  RECOVERY: { name: 'System Recovery', in: 'Affected assets + containment results + backup catalogue', out: 'Readiness report, recovery tasks, verification report', tools: 'Simulated backup/restore · task tracker · verification checks', perm: 'Operates only inside the simulated environment. No real file operations.' },
  COMMANDER: { name: 'SOC Coordinator', in: 'Alerts from SENTINEL, JSON from all agents', out: 'Incident state machine, 12-stage workflow, priority, approvals, report', tools: 'Schema validation · risk prioritisation · KB (RAG) retrieval · notifications · ticketing', perm: 'Orchestrates only. A failing agent degrades the incident but never crashes the pipeline.' },
};
const dl = async (path, name) => { try { const r = await fetch(path, { credentials: 'same-origin' }); if (!r.ok) throw new Error((await r.json()).error); const a = document.createElement('a'); a.href = URL.createObjectURL(await r.blob()); a.download = name; a.click(); } catch (e) { toast(e.message, 'bad'); } };
const stepper = (wf) => `<div class="wf">${wf.map((s, i) => `<div class="s ${s.status}" title="${esc(s.note || '')}"><div class="dot">${s.status === 'done' ? '✓' : s.status === 'failed' ? '!' : i + 1}</div><div class="n">${esc(s.label)}</div><div class="a">${esc(s.agent)}</div>${s.note ? `<div class="mut" style="font-size:9.5px;margin-top:2px">${esc(s.note.length > 44 ? s.note.slice(0, 43) + '…' : s.note)}</div>` : ''}</div>`).join('')}</div>`;
const incRow = (i) => `<tr class="click" onclick="location.hash='#/incidents/${i.id}'"><td class="mono">${i.id}</td><td>${esc(i.title)}<div class="mut" style="font-size:11px">${i.categories.map(esc).join(' · ')}</div></td><td>${sevChip(i.severity)}</td><td><b>${i.priority}</b></td><td class="mono">${i.riskScore}</td><td>${esc(i.status)}</td><td>${originChip(i.origin)}</td><td class="mono dim">${fmtT(i.createdAt)}</td></tr>`;
const incTable = (list) => list.length ? `<table><tr><th>ID</th><th>Incident</th><th>Severity</th><th>Pri</th><th>Risk</th><th>Status</th><th>Origin</th><th>Detected</th></tr>${list.map(incRow).join('')}</table>` : '<div class="empty">No incidents yet. Launch a scenario to see PHOENIX X work.</div>';
const apprCard = (a) => `<div class="appr"><div class="between"><b>${esc(a.action.description)}</b>${tierChip(a.action.tier)}</div><div class="dim" style="font-size:12px;margin:4px 0">${esc(a.incidentId)} · ${esc(a.action.reason)}</div><div class="row"><button class="btn ok sm" data-a="approve" data-id="${esc(a.action.id)}" ${isAdmin() ? '' : 'disabled title="admin role required"'}>✓ Allow</button><button class="btn no sm" data-a="reject" data-id="${esc(a.action.id)}" ${isAdmin() ? '' : 'disabled'}>✕ Disallow</button>${isAdmin() ? '' : '<span class="mut" style="font-size:11px">sign in as admin to decide</span>'}</div></div>`;
const agentMini = () => `<div class="grid g2" style="gap:8px">${Object.entries(S.agents).map(([k, a]) => `<div class="row" style="gap:8px"><span class="dotst ${a.state === 'working' ? 'w' : 'i'}"></span><b style="color:${AGENT_COL[k]};font-size:12px">${k}</b><span class="mut" style="font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:140px">${esc(a.state === 'working' ? a.current || 'working' : a.runs + ' runs')}</span></div>`).join('')}</div>`;
const msgHtml = (m, i) => `<div class="msg" data-a="msg"><div class="h"><span class="ag ag-${m.from}">${m.from}</span>→<span class="ag ag-${m.to}">${m.to}</span><span class="chip">${esc(m.type)}</span><span class="sp"></span>${fmtT(m.ts)}</div><pre>${esc(JSON.stringify(m.payload, null, 1))}</pre></div>`;

const PAGE_FN = {
  command() {
    const latest = S.incidents[0]; if (latest) { U.graphInc = latest.id; if (U.detail?.id !== latest.id) refreshDetail(latest.id); }
    const d = latest && U.detail?.id === latest.id ? U.detail : null, m = S.metrics;
    const taskT = S.incidents.reduce((a, i) => a + i.tasks.total, 0), taskD = S.incidents.reduce((a, i) => a + i.tasks.done, 0);
    return `<div class="between" style="margin-bottom:14px"><div><h1>Security Command Centre</h1><p class="sub" style="margin:0">Autonomous SOC · five stages: Detect → Investigate → Contain → Recover → Learn</p></div><a href="#/response" class="chip ${S.autonomy?.mode === 'full' ? 'sev-high' : S.autonomy?.mode === 'balanced' ? 'live' : 'sim'}" style="text-decoration:none" title="Change AI autonomy">AI mode: ${esc(S.autonomy?.modes?.[S.autonomy?.mode]?.label || '—')}</a></div>
    <div class="grid g-main" style="margin-bottom:14px">${S.settings.mode === 'production' ? `<div class="card"><h2 style="margin:0">Production mode</h2><div class="dim" style="font-size:12px">No simulated data. Every containment action needs a human approval (${S.settings.approvalTimeoutMin || 0} min timeout, then auto-denied). Connect your log sources in <a href="#/settings">Settings → Ingest keys</a>.</div></div>` : `<button class="launch" data-a="launch" data-id="signature" ${canAct() ? '' : 'disabled'}>⚡ LAUNCH CYBER ATTACK SIMULATION<small>Synthetic attack on a simulated enterprise · agents investigate, you approve containment · ~3–5 min</small></button>
      <div class="card row" style="justify-content:space-between"><div><h2 style="margin:0">Demo mode</h2><div class="dim" style="font-size:12px">${isAdmin() ? 'You are admin: you will approve containment.' : 'Sign in as admin to approve actions, or enable autopilot.'}</div></div><label class="toggle"><input type="checkbox" data-a="autopilot" ${S.settings.autopilot ? 'checked' : ''} ${isAdmin() ? '' : 'disabled'}><span></span><small class="dim">Autopilot</small></label></div>`}</div>
    <div class="grid g6" style="margin-bottom:14px">
      <div class="card" style="grid-row:span 1;display:grid;place-items:center">${ring()}</div>
      ${[['Active incidents', 'activeIncidents', 'rgba(255,106,26,.25)'], ['Critical threats', 'criticalThreats', 'rgba(255,59,79,.3)'], ['Events detected', 'eventsToday', 'rgba(56,214,255,.25)'], ['Compromised assets', 'compromisedAssets', 'rgba(255,210,74,.25)'], ['Avg time to contain', 'avgContainSec', 'rgba(61,220,151,.25)']].map(([l, k, c]) => `<div class="card kpi" style="--k:${c}"><div class="l">${l}</div><div class="v" data-kpi="${k}">${k === 'avgContainSec' ? (m[k] == null ? '—' : m[k] + 's') : m[k] ?? 0}</div></div>`).join('')}</div>
    ${pendingActions().length ? `<div class="card" style="margin-bottom:14px;border-color:rgba(255,210,74,.5)"><h2>⏳ The AI needs your OK <span class="dim" style="font-size:12px">— press Allow and the AI does it. You can undo it later.</span></h2>${pendingActions().map(apprCard).join('')}</div>` : ''}
    <div class="grid g-main" style="margin-bottom:14px"><div class="card"><div class="between"><h2 style="margin:0">Incident response workflow</h2>${latest ? `<a href="#/incidents/${latest.id}">${latest.id} · ${esc(latest.state)} →</a>` : ''}</div>${latest ? `<div class="row" style="margin:8px 0">${sevChip(latest.severity)}<b>${esc(latest.title)}</b><span class="chip">${latest.priority}</span><span class="mut">risk ${latest.riskScore}</span></div>${stepper(latest.workflow)}` : '<div class="empty">Idle. Click <b>LAUNCH CYBER ATTACK SIMULATION</b>.</div>'}</div>
      <div class="card"><h2>Agent activity</h2>${agentMini()}<h2 style="margin-top:14px">Recovery progress</h2><div class="between"><span class="dim">${taskD}/${taskT} tasks</span><b>${taskT ? Math.round((taskD / taskT) * 100) : 0}%</b></div><div class="bar g"><i style="width:${taskT ? (taskD / taskT) * 100 : 0}%"></i></div></div></div>
    <div class="grid g-3c"><div class="card pad0"><div class="between" style="padding:12px 14px 6px"><h2 style="margin:0">Live security event feed</h2><a href="#/live">open monitor</a></div><div class="feed" id="feed" style="--h:340px">${S.events.slice(-60).reverse().map((e) => evRow(e)).join('')}</div></div>
      <div class="card"><div class="between"><h2 style="margin:0">Attack visualisation</h2><a href="#/graph">full graph</a></div>${d ? graphSvg(d, { small: true }) : '<div class="empty">No active attack graph</div>'}</div>
      <div class="card"><h2>Agent message bus</h2><div style="max-height:360px;overflow:auto">${S.messages.slice(-12).reverse().map(msgHtml).join('') || '<div class="empty">No agent traffic yet</div>'}</div></div></div>
    <div class="card" style="margin-top:14px"><h2>Incident timeline</h2>${d ? `<div class="tl" style="max-height:260px;overflow:auto">${d.investigation?.timeline.map((t) => `<div class="it ${t.suspicious ? 'sus' : ''}"><div class="ph">${esc(t.phase)} · ${fmtT(t.ts)}</div>${esc(t.summary)}</div>`).join('') || ''}</div>` : '<div class="empty">Timeline appears when an incident is investigated.</div>'}</div>`;
  },
  live() {
    const sources = ['authentication', 'application', 'system', 'network', 'api', 'file', 'cloud'], cnt = S.analytics.bySource || {};
    const list = S.events.slice().reverse().filter((e) => U.feedFilter === 'all' || e.source === U.feedFilter || e.origin === U.feedFilter);
    return `<h1>Live Threat Monitor</h1><p class="sub">Real-time event stream over WebSocket. <b>SIM</b> = generated background traffic · <b>ATTACK SIM</b> = scripted scenario · <b>LIVE</b> = real data posted to <span class="mono">/api/ingest</span>.</p>
    <div class="grid g4" style="margin-bottom:14px">${sources.slice(0, 4).concat([]).map((s) => `<div class="card kpi"><div class="l">${s}</div><div class="v">${cnt[s] || 0}</div></div>`).join('')}</div>
    <div class="card"><div class="row" style="margin-bottom:10px"><select id="ff" data-a="feedfilter"><option value="all">All events</option>${['generated', 'scenario', 'ingested'].map((o) => `<option value="${o}" ${U.feedFilter === o ? 'selected' : ''}>origin: ${o}</option>`).join('')}${sources.map((s) => `<option value="${s}" ${U.feedFilter === s ? 'selected' : ''}>source: ${s}</option>`).join('')}</select><label class="toggle"><input type="checkbox" data-a="pause" ${U.feedPaused ? 'checked' : ''}><span></span><small class="dim">Pause</small></label><span class="sp"></span><span class="dim mono">${S.metrics.eventsToday || 0} events total</span></div>
    <div class="feed" id="feed" style="--h:560px">${list.slice(0, 150).map((e) => evRow(e)).join('')}</div></div>`;
  },
  agents() {
    return `<h1>AI Agent Operations</h1><p class="sub">Six specialised agents. They only exchange schema-validated JSON through COMMANDER. Click a message to see its payload.</p>
    <div class="grid g3" style="margin-bottom:14px">${Object.entries(AGENTS).map(([k, a]) => { const st = S.agents[k] || {}; return `<div class="card agent ${st.state === 'working' ? 'working' : ''}"><div class="hd"><div class="av" style="color:${AGENT_COL[k]}">${k.slice(0, 2)}</div><div><b style="color:${AGENT_COL[k]}">${k}</b><div class="dim" style="font-size:12px">${a.name}</div></div><span class="sp"></span><span class="dotst ${st.state === 'working' ? 'w' : 'i'}"></span></div>
      <div class="dim" style="font-size:12px;min-height:16px">${st.state === 'working' ? '▶ ' + esc(st.current || 'working') : 'idle'}</div><dl class="kv"><dt>Input</dt><dd>${esc(a.in)}</dd><dt>Output</dt><dd>${esc(a.out)}</dd><dt>Tools</dt><dd>${esc(a.tools)}</dd><dt>Permissions</dt><dd>${esc(a.perm)}</dd><dt>Runs / fails</dt><dd class="mono">${st.runs || 0} / ${st.failures || 0}${st.lastMs ? ` · last ${st.lastMs}ms` : ''}</dd></dl></div>`; }).join('')}</div>
    <div class="card"><h2>Inter-agent message log (structured JSON)</h2><div style="max-height:520px;overflow:auto">${S.messages.slice().reverse().map(msgHtml).join('') || '<div class="empty">No messages yet — launch a scenario.</div>'}</div></div>`;
  },
  incidents(arg) {
    if (!arg) return `<h1>Incident Investigation</h1><p class="sub">Every incident has a dedicated page: evidence, agent analysis, containment, approvals, recovery and resolution.</p><div class="card pad0">${incTable(S.incidents)}</div>`;
    const i = U.detail; if (!i || i.id !== arg) return `<div class="empty">Loading ${esc(arg)}…</div>`;
    const tabs = [['overview', 'Overview'], ['timeline', 'Timeline'], ['evidence', 'Evidence'], ['graph', 'Attack graph'], ['intel', 'Threat intel'], ['containment', 'Containment & approvals'], ['recovery', 'Recovery'], ['notes', 'Notes'], ['audit', 'Audit'], ['report', 'Report']];
    const inv = i.investigation;
    const head = `<div class="card"><div class="between"><div><div class="row"><span class="mono dim">${i.id}</span>${sevChip(i.severity)}<span class="chip">${i.priority}</span><span class="chip">${esc(i.state)}</span>${originChip(i.origin)}${i.degraded ? '<span class="chip sev-high">degraded agent</span>' : ''}</div><h1 style="margin-top:6px">${esc(i.title)}</h1><div class="dim">Detected ${fmtDT(i.createdAt)} · risk <b>${i.riskScore}</b>/100 · threat type: ${[...new Set(i.alerts.map((a) => a.category))].map(esc).join(', ')}${i.ticket ? ` · ticket <b>${esc(i.ticket.id)}</b> <span class="chip ${i.ticket.confirmed ? 'live' : 'sim'}">${i.ticket.confirmed ? 'jira confirmed' : 'simulated'}</span>` : ''}</div></div>
      ${i.interrupted ? `<div class="note" style="border-color:#ffb347"><b>⚠ Interrupted by a server restart.</b> The workflow was not resumed automatically and pending approvals were cancelled. Review the evidence, then ${isAdmin() ? '<button class="btn pri sm" data-a="resume" data-id="' + esc(i.id) + '">Resume workflow</button>' : 'ask an admin to resume it'} or handle it manually.</div>` : ''}<div class="row"><select data-a="status" ${canAct() ? '' : 'disabled'}>${['Open', 'In Progress', 'Escalated', 'False Positive', 'Resolved', 'Closed'].map((s) => `<option ${i.status === s ? 'selected' : ''}>${s}</option>`).join('')}</select><input id="analyst" placeholder="Assign analyst" value="${esc(i.analyst || '')}" style="width:140px" ${canAct() ? '' : 'disabled'}><button class="btn sm" data-a="assign" ${canAct() ? '' : 'disabled'}>Assign</button><button class="btn sm" data-a="dlmd" ${i.report ? '' : 'disabled'}>⬇ Report</button><button class="btn sm" data-a="dljson">⬇ Evidence bundle</button></div></div>${stepper(i.workflow)}</div>`;
    let body = '';
    const t = U.tab;
    if (t === 'overview') body = briefCard(i) + `<div class="grid g2"><div class="card"><h2>Executive summary</h2><p>${esc(inv?.summary || 'Investigating…')}</p>${inv?.aiNarrative ? `<div class="note"><b>AI briefing</b> (${esc(inv.aiNarrative.model)} — prose over the structured facts, not evidence)<br>${esc(inv.aiNarrative.text)}</div>` : ''}<dl class="kv"><dt>Confidence</dt><dd><b>${esc(inv?.confidence || '—')}</b> <span class="mut">${esc(inv?.confidenceReason || '')}</span></dd><dt>Entry point</dt><dd>${esc(inv?.entryPoint?.description || '—')} <span class="chip">${esc(inv?.entryPoint?.basis || '')}</span><div class="mut" style="font-size:11px">${esc(inv?.entryPoint?.note || '')}</div></dd><dt>Disposition</dt><dd>${esc(i.disposition)}</dd><dt>Resolution</dt><dd>${esc(i.resolution || 'open')}</dd></dl></div>
      <div class="card"><h2>Risk prioritisation (explainable)</h2>${i.priorityBreakdown ? `<div class="between"><b style="font-size:22px">${i.priority}</b><span class="dim">score ${i.priorityBreakdown.score}/100</span></div>${i.priorityBreakdown.factors.map((f) => `<div style="margin:7px 0"><div class="between" style="font-size:12px"><span>${esc(f.name)} <span class="mut">×${f.weight}</span></span><b class="mono">${f.value}</b></div><div class="bar"><i style="width:${f.value}%"></i></div></div>`).join('')}` : '…'}</div></div>
      <div class="card" style="margin-top:14px"><h2>Explainable detections</h2><table><tr><th>What happened</th><th>Why it was flagged</th><th>Confidence</th><th>Detector</th><th>Recommended</th></tr>${i.alerts.map((a) => `<tr><td>${esc(a.explain?.whatHappened)}<div class="mut mono" style="font-size:10.5px">${esc(a.rule)} · risk ${a.riskScore} · ${a.evidence.length} evidence event(s)</div></td><td>${esc(a.explain?.whyFlagged)}</td><td class="mono">${Math.round((a.explain?.confidence || 0) * 100)}%</td><td>${esc(a.explain?.detection)}</td><td>${esc(a.explain?.recommended)}</td></tr>`).join('')}</table></div>
      <div class="grid g2" style="margin-top:14px"><div class="card"><h2>✓ Confirmed by evidence</h2>${(inv?.confirmedFindings || []).map((f) => `<div class="note" style="border-color:var(--gr)">${esc(f.statement)}</div>`).join('') || '—'}</div><div class="card"><h2>? Hypotheses (unconfirmed)</h2>${(inv?.hypotheses || []).map((h) => `<div class="note" style="border-color:var(--yl)">${esc(h.statement)} <span class="chip">${esc(h.confidence)}</span><div class="mut">To confirm: ${esc(h.toConfirm)}</div></div>`).join('') || '—'}</div></div>
      <div class="grid g2" style="margin-top:14px"><div class="card"><h2>MITRE ATT&CK</h2>${(inv?.techniques || []).map((x) => `<div style="margin:6px 0"><span class="pill ${x.status === 'evidence-supported' ? 'sup' : 'hyp'}">${esc(x.id)}</span> <b>${esc(x.name)}</b> <span class="chip">${esc(x.status)}</span><div class="mut" style="font-size:11px">${esc(x.basis)}</div></div>`).join('') || '—'}<div class="note">Techniques are only marked <b>evidence-supported</b> when a detection rule directly observed the behaviour. Everything else is a hypothesis.</div></div>
      <div class="card"><h2>Knowledge base (RAG) — matched playbooks</h2>${i.playbooks.map((p) => `<div class="note"><b>${esc(p.id)} · ${esc(p.title)}</b><div class="mut">${esc(p.excerpt)}</div></div>`).join('') || '—'}</div></div>
      ${i.emailAnalysis ? `<div class="card" style="margin-top:14px"><h2>Reported email — static analysis</h2><div class="note">${esc(i.emailAnalysis.note)}</div><dl class="kv"><dt>URLs</dt><dd class="mono">${i.emailAnalysis.urls.map(esc).join('<br>')}</dd><dt>Red flags</dt><dd>${i.emailAnalysis.flags.map((f) => `<div>⚠ ${esc(f)}</div>`).join('')}</dd><dt>Recipients</dt><dd>${i.emailAnalysis.recipients.map(esc).join(', ')}</dd><dt>Clicked</dt><dd class="st-bad">${i.emailAnalysis.clickers.map(esc).join(', ') || 'none observed'}</dd></dl></div>` : ''}`;
    if (t === 'timeline') body = `<div class="card"><h2>Reconstructed attack timeline</h2><div class="tl">${(inv?.timeline || []).map((x) => `<div class="it ${x.suspicious ? 'sus' : ''}"><div class="ph">${esc(x.phase)} · ${fmtT(x.ts)} · ${esc(x.source)} ${originChip(x.origin)}</div>${esc(x.summary)}</div>`).join('')}</div></div>`;
    if (t === 'evidence') body = `<div class="card"><h2>Preserved evidence</h2><div class="note">Frozen at ${fmtDT(i.evidence.preservedAt)} · ${i.evidence.count} events · SHA-256 <span class="mono">${esc(i.evidence.sha256)}</span></div><table><tr><th>Time</th><th>ID</th><th>Event</th><th>Origin</th></tr>${i.evidence.items.map((e) => `<tr><td class="mono">${fmtT(e.ts)}</td><td class="mono mut">${esc(e.id)}</td><td>${evDesc(e)}</td><td>${originChip(e.origin)}</td></tr>`).join('')}</table></div>`;
    if (t === 'graph') { U.graphInc = i.id; body = `<div class="grid" style="grid-template-columns:minmax(0,2.2fr) minmax(0,1fr)"><div>${graphSvg(i)}</div>${nodePanel(i)}</div>`; }
    if (t === 'intel') body = `<div class="card"><h2>Threat intelligence</h2><p>${esc(i.intel?.summary || '')}</p>${intelTable(i.intel?.indicators || [])}</div>`;
    if (t === 'containment') body = `<div class="card"><h2>Containment plan (GUARDIAN)</h2><div class="note">${esc(i.plan?.note || '')}</div>${actionTable(i)}</div><div class="grid g2" style="margin-top:14px"><div class="card"><h2>Restricted — manual only</h2>${(i.plan?.manualOnly || []).map((m) => `<div class="note" style="border-color:var(--rd)">${tierChip('restricted')} <b>${esc(m.description)}</b><div class="mut">${esc(m.why)}</div></div>`).join('') || '<div class="dim">None</div>'}</div><div class="card"><h2>Approval history</h2>${i.approvals.map((a) => `<div class="note">${a.decision === 'approved' ? '✅' : '❌'} <b>${esc(a.description)}</b><div class="mut">${esc(a.by)} · ${fmtDT(a.ts)} ${esc(a.comment)}</div></div>`).join('') || '<div class="dim">No approvals requested</div>'}</div></div>`;
    if (t === 'recovery') body = recoveryBlock(i);
    if (t === 'notes') body = `<div class="card"><h2>Investigation notes</h2>${i.notes.map((n) => `<div class="note"><b>${esc(n.by)}</b> · ${fmtDT(n.ts)}<br>${esc(n.text)}</div>`).join('') || '<div class="dim">No notes yet</div>'}<textarea id="note" placeholder="Add an investigation note…" ${canAct() ? '' : 'disabled'}></textarea><div style="margin-top:8px"><button class="btn pri sm" data-a="note" ${canAct() ? '' : 'disabled'}>Add note</button></div></div>`;
    if (t === 'audit') body = `<div class="card"><h2>Audit history (${i.audit.length})</h2>${auditTable(i.audit)}</div>`;
    if (t === 'report') body = `<div class="card"><div class="between"><h2 style="margin:0">Final incident report</h2><button class="btn sm" data-a="dlmd" ${i.report ? '' : 'disabled'}>⬇ Download .md</button></div>${i.report ? `<div class="md" style="margin-top:10px">${esc(i.report)}</div>` : '<div class="empty">Generated at the end of the workflow.</div>'}</div>`;
    return `<a href="#/incidents" class="dim">← all incidents</a><div style="height:8px"></div>${head}<div class="tabs">${tabs.map(([k, l]) => `<a data-a="tab" data-id="${k}" class="${t === k ? 'on' : ''}">${l}</a>`).join('')}</div>${body}`;
  },
  graph() {
    const list = S.incidents; if (!list.length) return `<h1>Attack Graph</h1><div class="card empty">No incidents yet. Launch a scenario.</div>`;
    if (!U.graphInc || !list.some((x) => x.id === U.graphInc)) U.graphInc = list[0].id; if (U.detail?.id !== U.graphInc) refreshDetail(U.graphInc);
    const d = U.detail?.id === U.graphInc ? U.detail : null;
    return `<div class="between"><div><h1>Attack Graph</h1><p class="sub">Entities (users, devices, IPs, servers, files, apps) linked through security events. Orange dashed line = reconstructed attack path. Click a node to inspect evidence.</p></div><select data-a="graphpick">${list.map((x) => `<option value="${x.id}" ${x.id === U.graphInc ? 'selected' : ''}>${x.id} — ${esc(x.title)}</option>`).join('')}</select></div>
    ${d ? `<div class="grid" style="grid-template-columns:minmax(0,2.3fr) minmax(0,1fr)"><div>${graphSvg(d)}<div class="card" style="margin-top:14px"><h2>Attack path</h2>${d.graph ? '' : ''}<div class="row">${(d.investigation.graph.attackPath || []).map((id, k) => { const n = d.investigation.graph.nodes.find((x) => x.id === id); return `${k ? '<span class="mut">→</span>' : ''}<span class="pill" style="cursor:pointer" data-a="node" data-id="${esc(id)}">${esc(n?.label || id)}</span>`; }).join('')}</div></div></div>${nodePanel({ ...d, graph: d.investigation.graph, evidence: d.evidence })}</div>` : '<div class="empty">Loading graph…</div>'}`;
  },
  intel() {
    const all = allDetails(), inds = {}; all.forEach((i) => (i.intel?.indicators || []).forEach((x) => (inds[x.indicator] = x)));
    const mitre = S.analytics.mitre || {};
    return `<h1>Threat Intelligence</h1><p class="sub">ORACLE enriches IPs, domains and hashes via ${S.integrations['Threat intel (VirusTotal)']}. <b>An unrecognised indicator is “unknown”, never “malicious”.</b></p>
    <div class="grid g2"><div class="card"><h2>Indicator lookup</h2><form data-f="lookup" class="row"><select name="type"><option>ip</option><option>domain</option><option>hash</option></select><input name="value" placeholder="198.19.66.14 / secure-payroll-login.example" style="flex:1" required><button class="btn pri">Check</button></form><div id="lookres" style="margin-top:10px"></div></div>
    <div class="card"><h2>Security knowledge base (RAG)</h2><form data-f="kb" class="row"><input name="q" placeholder="e.g. ransomware backup restore" style="flex:1" required><button class="btn pri">Search</button></form><div id="kbres" style="margin-top:10px;max-height:240px;overflow:auto"></div></div></div>
    <div class="card" style="margin-top:14px"><h2>Indicators seen in incidents (${Object.keys(inds).length})</h2>${intelTable(Object.values(inds))}</div>
    <div class="card" style="margin-top:14px"><h2>MITRE ATT&CK coverage</h2>${Object.keys(mitre).length ? `<table><tr><th>Technique</th><th>Name</th><th>Status</th><th>Incidents</th></tr>${Object.entries(mitre).map(([k, v]) => `<tr><td><span class="pill ${v.status === 'evidence-supported' ? 'sup' : 'hyp'}">${esc(k)}</span></td><td>${esc(v.name)}</td><td>${esc(v.status)}</td><td>${v.n}</td></tr>`).join('')}</table>` : '<div class="empty">No techniques yet</div>'}</div>`;
  },
  response() {
    const all = allDetails(), acts = all.flatMap((i) => i.containment.map((a) => ({ ...a, inc: i.id })));
    return `<h1>Automated Response</h1><p class="sub">Permission-based execution. GUARDIAN can only call whitelisted functions, and the policy engine re-checks every action at execution time.</p>
    <div class="grid g3" style="margin-bottom:14px"><div class="card">${tierChip('automatic')}<p class="dim">The AI does this alone (depends on the mode below): block IPs, revoke sessions/tokens, restrict a resource, suspend a suspicious account. You can unblock.</p></div><div class="card">${tierChip('approval')}<p class="dim">Waits for an admin: isolate a host, change cloud policy/bucket, protected entities, production assets. In Full AI mode the AI does these too.</p></div><div class="card">${tierChip('restricted')}<p class="dim">Destructive / shutdown / security-control changes. Never executed by the agent — even if "approved". Listed as manual-only.</p></div></div>
    ${autonomyCard()}${containCard()}
    <div class="card" style="margin-bottom:14px"><h2>Approval queue</h2>${pendingActions().map(apprCard).join('') || '<div class="empty">No actions waiting for approval</div>'}</div>
    <div class="card" style="margin-bottom:14px"><h2>All containment actions (${acts.length})</h2>${acts.length ? `<table><tr><th>Incident</th><th>Action</th><th>Tier</th><th>Status</th><th>Result</th></tr>${acts.map((a) => `<tr><td class="mono">${a.inc}</td><td>${esc(a.description)}<div class="mut" style="font-size:11px">${esc(a.reason)}</div></td><td>${tierChip(a.tier)}</td><td>${statusChip(a.status)}</td><td class="dim">${esc(a.result?.detail || a.error || '')}${a.approvedBy ? `<div class="mut">by ${esc(a.approvedBy)}</div>` : ''}</td></tr>`).join('')}</table>` : '<div class="empty">None yet</div>'}</div>
    <div class="card"><h2>Policy tester — prove the guard rails</h2><p class="dim">Admin only. Try a restricted action: it will be refused even with approval.</p><form data-f="policy" class="row"><select name="type">${['block_ip', 'revoke_sessions', 'disable_account', 'isolate_host', 'shutdown_host', 'delete_data', 'wipe_host', 'modify_security_control', 'rm_rf_everything'].map((t) => `<option>${t}</option>`).join('')}</select><input name="target" placeholder='{"host":"prod-db-01"}' value='{"host":"srv-files-01"}' style="flex:1;font-family:var(--mono)"><label class="row dim"><input type="checkbox" name="approve" checked> approve</label><button class="btn pri" ${isAdmin() ? '' : 'disabled'}>Attempt</button></form><pre id="polres" class="md" style="margin-top:10px;min-height:40px"></pre></div>`;
  },
  recovery() {
    const all = allDetails(), bk = S.assets.backups || {};
    return `<h1>Recovery Centre</h1><p class="sub">Backup readiness, recovery task lists and post-recovery verification. Restores are simulated inside the sandbox.</p>
    <div class="card" style="margin-bottom:14px"><h2>Backup inventory</h2><table><tr><th>Host</th><th>Backup</th><th>Taken</th><th>Verified</th><th>Immutable</th><th>Size</th></tr>${Object.entries(S.assets.hosts || {}).map(([h]) => (bk[h] || [{ none: true }]).map((b, k) => b.none ? `<tr><td class="mono">${h}</td><td colspan="5" class="st-bad">⚠ NO BACKUP — recovery would require a manual rebuild</td></tr>` : `<tr><td class="mono">${k ? '' : h}</td><td class="mono">${b.id}</td><td class="dim">${fmtDT(b.ts)}</td><td>${b.verified ? '<span class="st-ok">✓ verified</span>' : '<span class="st-warn">unverified</span>'}</td><td>${b.immutable ? '✓' : '—'}</td><td>${b.sizeGB} GB</td></tr>`).join('')).join('')}</table></div>
    ${all.filter((i) => i.recovery.tasks.length || i.recovery.readiness.length).map((i) => `<div style="margin-bottom:14px"><h3><a href="#/incidents/${i.id}">${i.id}</a> — ${esc(i.title)}</h3>${recoveryBlock(i)}</div>`).join('') || '<div class="card empty">Recovery plans appear once an incident reaches the recovery stage.</div>'}`;
  },
  assets() {
    const a = S.assets; if (!a.users) return '<div class="empty">Loading…</div>';
    return `<h1>Asset Inventory</h1><p class="sub">The simulated enterprise. Containment actions visibly change these assets.</p>
    <div class="grid g2"><div class="card"><h2>Identities</h2><table><tr><th>User</th><th>Dept</th><th>Role</th><th>Status</th><th>Sessions</th><th>MFA</th></tr>${Object.entries(a.users).map(([k, u]) => `<tr><td class="mono">${k}</td><td>${u.dept}</td><td>${u.role}</td><td class="${u.status === 'active' ? 'st-ok' : 'st-bad'}">${u.status}</td><td>${u.sessions}</td><td>${u.mfa ? '✓' : '<span class="st-warn">none</span>'}</td></tr>`).join('')}</table></div>
    <div class="card"><h2>Hosts</h2><table><tr><th>Host</th><th>Kind</th><th>Env</th><th>Criticality</th><th>State</th></tr>${Object.entries(a.hosts).map(([k, h]) => `<tr><td class="mono">${k}</td><td>${h.kind}</td><td>${h.env === 'production' ? '<span class="chip sev-high">production</span>' : 'sandbox'}</td><td>${h.criticality}</td><td class="${h.isolated ? 'st-bad' : 'st-ok'}">${h.status}${h.restoredFrom ? ' · restored ' + h.restoredFrom : ''}</td></tr>`).join('')}</table></div></div>
    <div class="grid g3" style="margin-top:14px"><div class="card"><h2>Data resources</h2>${Object.entries(a.resources).map(([k, r]) => `<div class="between" style="margin:5px 0"><span class="mono" style="font-size:12px">${esc(k)}</span><span>${r.restricted ? '<span class="chip t-restricted">access restricted</span>' : `<span class="chip">${r.sensitivity}</span>`}</span></div>`).join('')}</div>
    <div class="card"><h2>Cloud</h2>${Object.entries(a.cloud.roles).map(([k, r]) => `<div class="between" style="margin:5px 0"><span class="mono" style="font-size:12px">${k}</span><span class="${r.policies.some((p) => /Admin/.test(p)) ? 'st-bad' : 'dim'}" style="font-size:11px">${r.policies.join(', ') || '—'}</span></div>`).join('')}${Object.entries(a.cloud.buckets).map(([k, b]) => `<div class="between" style="margin:5px 0"><span class="mono" style="font-size:12px">s3://${k}</span><span class="${b.public ? 'st-bad' : 'st-ok'}">${b.public ? 'PUBLIC' : 'private'}</span></div>`).join('')}<div class="between" style="margin-top:8px"><span>Audit logging</span><span class="st-ok">${a.cloud.trailLogging ? 'enabled' : 'DISABLED'}</span></div></div>
    <div class="card"><h2>Firewall blocklist</h2>${a.blockedIPs.length ? a.blockedIPs.map((ip) => `<div class="mono st-bad">⛔ ${esc(ip)}</div>`).join('') : '<div class="dim">No blocked IPs</div>'}</div></div>`;
  },
  analytics() {
    const A = S.analytics, all = allDetails();
    const pri = {}; S.incidents.forEach((i) => (pri[i.priority] = (pri[i.priority] || 0) + 1));
    return `<h1>Security Analytics</h1><p class="sub">Event throughput, detection mix and response performance.</p>
    <div class="card" style="margin-bottom:14px"><div class="between"><h2 style="margin:0">Events per 30s (last 10 min)</h2><span class="dim" style="font-size:11px"><span style="color:#38d6ff">■</span> generated &nbsp;<span style="color:#ff4d5e">■</span> attack simulation &nbsp;<span style="color:#3ddc97">■</span> live ingested</span></div>${stackedBars(A.series || [], ['generated', 'scenario', 'ingested'], ['#38d6ff', '#ff4d5e', '#3ddc97'], 900, 150)}</div>
    <div class="grid g3"><div class="card"><h2>Events by source</h2>${hbars(A.bySource || {}, '#38d6ff')}</div><div class="card"><h2>Alerts by category</h2>${hbars(A.cats || {}, '#ff6a1a')}</div><div class="card"><h2>Detections by rule</h2>${hbars(A.rules || {}, '#a78bfa')}</div></div>
    <div class="grid g3" style="margin-top:14px"><div class="card"><h2>Incidents by priority</h2>${hbars(pri, '#ff4d5e')}</div><div class="card"><h2>Time to containment</h2>${(A.contain || []).map((c) => `<div class="between"><span class="mono">${c.id}</span><b>${c.sec}s</b></div>`).join('') || '<div class="empty">No containment yet</div>'}<div class="note">Detection → first containment action. Approval wait time is included.</div></div><div class="card"><h2>Agent performance</h2>${Object.entries(S.agents).map(([k, a]) => `<div class="between" style="margin:4px 0"><b style="color:${AGENT_COL[k]};font-size:12px">${k}</b><span class="mono dim">${a.runs} runs · ${a.failures} fail</span></div>`).join('')}</div></div>`;
  },
  audit() {
    if (!U.auditLoaded) { U.auditLoaded = true; api('/api/audit?limit=500').then((d) => { S.audit = d; later(50); }); }
    const f = U.auditFilter.toLowerCase(), rows = S.audit.slice().reverse().filter((e) => !f || JSON.stringify(e).toLowerCase().includes(f));
    return `<h1>Audit Logs</h1><p class="sub">Every agent decision, action, approval and login. Entries are hash-chained: altering one breaks verification of all following entries.</p>
    <div class="card"><div class="row" style="margin-bottom:10px"><input data-a="auditfilter" placeholder="Filter (actor, action, incident…)" value="${esc(U.auditFilter)}" style="width:300px"><button class="btn pri sm" data-a="verifychain">Verify hash chain</button><span id="chainres" class="mono"></span></div>${auditTable(rows.slice(0, 300))}</div>`;
  },
  connect() {
    if (!isAdmin()) return `<h1>Connect a Platform</h1><p class="sub">Only administrators can create connections. Ask an admin to connect your deployment platform.</p>`;
    setTimeout(loadConn, 0);
    const C = U.conn ||= { platform: 'vercel', method: null, created: null, cat: null, keys: [] };
    const cat = C.cat || []; const pl = cat.find((x) => x.id === C.platform) || cat[0]; if (!pl) return '<h1>Connect a Platform</h1><div class="empty">Loading…</div>';
    const m = pl.methods.find((x) => x.id === C.method) || pl.methods[0];
    const local = /^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|\[::1\])/.test(location.hostname);
    const key = C.created && C.created.method === pl.id + '/' + m.id ? C.created : null;
    const fill = (t) => t.replaceAll('{{HOOK}}', `${location.origin}/api/hook/${key ? key.key : '<YOUR-KEY>'}`).replaceAll('{{BASIC}}', `${location.protocol}//phoenix:${key ? key.key : '<YOUR-KEY>'}@${location.host}/api/ingest/heroku`).replaceAll('{{ORIGIN}}', location.origin).replaceAll('{{HOST}}', location.host).replaceAll('{{KEY}}', key ? key.key : '<YOUR-KEY>');
    const live = key && C.keys.find((k) => k.id === key.id);
    return `<h1>Connect a Platform</h1><p class="sub">Pick where your app runs, create a connection, paste two values into that platform, and PHOENIX X starts watching it. Each connection has its own revocable key.</p>
    ${local ? `<div class="note" style="border-color:#ffb347"><b>⚠ You are viewing PHOENIX X at ${esc(location.host)}.</b> Cloud platforms cannot reach a local address. Deploy PHOENIX X first (see docs/DEPLOY.md: Render, Fly.io, Railway or any VPS) and open the wizard from its public HTTPS address so the URLs below are correct.</div>` : ''}
    ${collectorCard()}
    <h2 style="margin-top:18px">Or connect with a webhook / log drain</h2>
    <div class="grid g4" style="gap:10px;margin:14px 0">${cat.map((x) => `<div class="card scn ${x.id === pl.id ? 'sel' : ''}" data-a="connplat" data-id="${x.id}" style="${x.id === pl.id ? 'outline:2px solid var(--accent,#ff6a1a)' : ''}"><div class="ic">${x.icon}</div><b>${esc(x.name)}</b><div class="dim" style="font-size:12px">${esc(x.blurb)}</div></div>`).join('')}</div>
    <div class="card"><div class="between"><h2 style="margin:0">${pl.icon} ${esc(pl.name)}</h2><div class="row">${pl.methods.map((x) => `<button class="btn ${x.id === m.id ? 'pri' : ''} sm" data-a="connmethod" data-id="${x.id}">${esc(x.title.split(' (')[0])}</button>`).join('')}</div></div>
      <h3 style="margin:14px 0 6px">${esc(m.title)}</h3>
      ${m.needs ? `<div class="dim" style="font-size:12px;margin-bottom:6px">${esc(m.needs)}</div>` : ''}
      ${key ? `<div class="note" style="border-color:#3ddc84"><b>Connection created. Copy your key now: it is shown once.</b><pre class="md" style="user-select:all">${esc(key.key)}</pre><div class="row"><button class="btn sm" data-a="conntest" data-id="${esc(key.id)}">Send test event</button> <span id="connstat" class="${live && live.received ? 'st-ok' : 'dim'}">${live && live.received ? `✓ PHOENIX has received ${live.received} event(s)${live.lastUsed ? ' · last ' + fmtDT(live.lastUsed) : ''}` : '⏳ waiting for the first event…'}</span></div></div>` :
      `<form data-f="newconn" class="grid g3" style="gap:8px;margin-bottom:10px"><label class="dim" style="font-size:11px">Connection name<input name="name" value="${esc(pl.id + '-' + m.id)}" style="width:100%"></label>
        ${m.signing ? `<label class="dim" style="font-size:11px">Signing secret (${m.signing})<input name="signingSecret" placeholder="same secret you set in ${esc(pl.name)}" style="width:100%"></label>` : ''}
        ${m.verify ? `<label class="dim" style="font-size:11px">Verify token (if ${esc(pl.name)} asks)<input name="verifyToken" style="width:100%"></label>` : ''}
        <button class="btn pri">Create connection</button></form>`}
      <ol style="line-height:1.7">${m.steps.map((t) => `<li>${esc(fill(t)).replace(/(https?:\/\/[^\s)]+|heroku drains:add [^<]+)/g, '<code class="mono" style="user-select:all">$1</code>')}</li>`).join('')}</ol>
      ${m.code ? `<pre class="md" style="user-select:all;white-space:pre-wrap">${esc(fill(m.code))}</pre>` : ''}
    </div>
    <div class="card" style="margin-top:14px"><h2>Your connections <button class="btn ghost sm" data-a="rotall" style="float:right">🔑 Rotate all keys</button></h2><table><tr><th>Name</th><th>Format</th><th>Events received</th><th>Last used</th><th></th></tr>${C.keys.map((k) => `<tr><td>${esc(k.name)}${k.disabled ? ' <span class="chip sev-high">revoked</span>' : ''}${k.signed ? ' <span class="chip live">signed</span>' : ''}</td><td class="mono">${esc(k.format)}</td><td>${k.received || 0}</td><td class="mut">${k.lastUsed ? fmtDT(k.lastUsed) : 'never'}</td><td>${k.disabled ? '' : `<button class="btn ghost sm" data-a="conntest" data-id="${esc(k.id)}">Test</button> <button class="btn ghost sm" data-a="keyrot" data-id="${esc(k.id)}">🔑 Rotate</button> <button class="btn no sm" data-a="keyrev" data-id="${esc(k.id)}">Revoke</button>`}</td></tr>`).join('') || '<tr><td colspan=5 class="dim">No connections yet</td></tr>'}</table></div>`;
  },
  settings() {
    const s = S.settings, ig = S.integrations, ops = S.ops || { outbox: [], tickets: [] };
    return `<h1>Settings & Integrations</h1><p class="sub">Signed in as <b>${esc(ME.user)}</b> (${ME.role}). Integrations never claim success without provider confirmation.</p>
    ${autonomyCard()}
    <div class="grid g2"><div class="card"><h2>Operating controls ${isAdmin() ? '' : '<span class="chip">admin only</span>'}</h2>
      ${[['autopilot', 'Autopilot (auto-complete human tasks — demo only)', s.autopilot], ['autoContain', 'Allow AUTOMATIC containment tier (sandbox/known-safe assets only)', s.autoContain], ['generator', 'Background event generator (simulated noise)', s.generator]].map(([k, l, v]) => `<div class="between" style="margin:10px 0"><span>${l}</span><label class="toggle"><input type="checkbox" data-a="setting" data-id="${k}" ${v ? 'checked' : ''} ${isAdmin() && !(PROD() && k !== 'autoContain') ? '' : 'disabled'}><span></span></label></div>`).join('')}
      <div class="between" style="margin:10px 0"><span>Workflow pace: <b class="mono">${s.paceMs}ms</b>/stage</span><input type="range" min="0" max="3000" step="100" value="${s.paceMs}" data-a="pace" ${isAdmin() ? '' : 'disabled'}></div>
      ${PROD() ? `<div class="between" style="margin:10px 0"><span>Approval timeout (min, 0 = never)</span><input type="number" min="0" max="1440" value="${s.approvalTimeoutMin || 0}" data-a="apptimeout" style="width:80px" ${isAdmin() ? '' : 'disabled'}></div>` : `<button class="btn no" data-a="reset" ${isAdmin() ? '' : 'disabled'}>Reset simulated environment</button>`}</div>
    <div class="card"><h2>Integrations</h2>${Object.entries(ig).map(([k, v]) => `<div class="between" style="margin:7px 0"><span>${esc(k)}</span><span class="chip ${/^configured|^connected|^enabled/.test(v) ? 'live' : 'sim'}">${esc(v)}</span></div>`).join('')}<div class="note">Set credentials in <span class="mono">.env</span> (see <span class="mono">.env.example</span>) and restart.</div></div></div>
    <div class="grid g2" style="margin-top:14px"><div class="card"><h2>Notification outbox</h2>${ops.outbox.map((n) => `<div class="note"><b>${esc(n.channel)}</b> <span class="chip ${n.status === 'delivered' ? 'live' : n.status === 'failed' ? 'sev-high' : 'sim'}">${esc(n.status)}</span> ${esc(n.subject)}<div class="mut" style="font-size:11px">${esc(n.confirmation || n.note || n.error || '')}</div></div>`).join('') || '<div class="dim">Nothing sent yet</div>'}</div>
    <div class="card"><h2>Tickets</h2>${ops.tickets.map((t) => `<div class="note"><b>${esc(t.id)}</b> ${esc(t.title)} <span class="chip ${t.confirmed ? 'live' : 'sim'}">${t.confirmed ? 'jira-confirmed' : 'local simulator'}</span><div class="mut" style="font-size:11px">${esc(t.priority)} · owner ${esc(t.owner)} · ${esc(t.status)}${t.error ? ' · ' + esc(t.error) : ''}</div></div>`).join('') || '<div class="dim">No tickets yet</div>'}</div></div>
    ${PROD() ? '' : `<div class="card" style="margin-top:14px"><h2>Scenarios</h2><div class="grid g3">${S.scenarios.map((x) => `<div class="card scn" data-a="launch" data-id="${x.id}"><div class="ic">${x.icon}</div><b>${esc(x.name)}</b><div class="dim" style="font-size:12px">${esc(x.blurb)}</div></div>`).join('')}</div></div>`}
    ${adminCards()}
    <div class="card" style="margin-top:14px"><h2>Connect real logs</h2><p class="dim">Create an <b>ingest key</b> above (one per source, bound to one format), then:</p><pre class="md">curl -X POST ${location.origin}/api/ingest/okta       -H "x-api-key: phx_…" -H "content-type: application/json" -d @okta-system-log.json
curl -X POST ${location.origin}/api/ingest/entra      -H "x-api-key: phx_…" -d @entra-signins.json
curl -X POST ${location.origin}/api/ingest/cloudtrail -H "x-api-key: phx_…" -d @cloudtrail.json
curl -X POST ${location.origin}/api/ingest/windows    -H "x-api-key: phx_…" -d @windows-events.json
curl -X POST ${location.origin}/api/ingest/syslog     -H "x-api-key: phx_…" -H "content-type: text/plain" --data-binary @auth.log
curl -X POST ${location.origin}/api/ingest/generic    -H "x-api-key: phx_…" -d '{"events":[{"source":"authentication","type":"login_failed","user":"alice","ip":"203.0.113.9"}]}'
</pre></div>`;
  },
};
// scenario launcher lives on Command Centre header + settings; also surfaced on incidents page when empty
const origIncidents = PAGE_FN.incidents;
PAGE_FN.incidents = (arg) => (arg ? origIncidents(arg) : `<h1>Incident Investigation</h1><p class="sub">Every incident has a dedicated page: evidence, agent analysis, containment, approvals, recovery and resolution.</p><div class="grid g3" style="margin-bottom:14px">${S.scenarios.map((x) => `<div class="card scn" data-a="launch" data-id="${x.id}"><div class="ic">${x.icon}</div><b>${esc(x.name)}</b><div class="dim" style="font-size:12px">${esc(x.blurb)}</div></div>`).join('')}</div><div class="card pad0">${incTable(S.incidents)}</div>`);

function statusChip(s) { const c = { executed: 'st-ok', rolled_back: 'dim', pending_approval: 'st-warn', denied: 'st-bad', blocked: 'st-bad', failed: 'st-bad', approved: 'st-ok', planned: 'dim', dry_run: 'st-warn', manual_required: 'st-warn' }[s] || ''; return `<b class="${c}">${esc(({ dry_run: 'DRY-RUN (not applied)', manual_required: 'MANUAL REQUIRED' }[s] || s.replace('_', ' ')))}</b>`; }
function actionTable(i) { return i.containment.length ? `<table><tr><th>Action</th><th>Tier</th><th>Status</th><th>Why / policy</th><th></th></tr>${i.containment.map((a) => `<tr><td>${esc(a.description)}</td><td>${tierChip(a.tier)}</td><td>${statusChip(a.status)}</td><td class="dim" style="font-size:12px">${esc(a.reason)}<div class="mut">${esc(a.policyReason)}</div>${a.result ? `<div class="st-ok">${esc(a.result.detail)} ${a.result.providerConfirmed ? '· confirmed' : ''}</div>` : ''}</td><td>${a.status === 'pending_approval' ? `<button class="btn ok sm" data-a="approve" data-id="${a.id}" ${isAdmin() ? '' : 'disabled'}>Approve</button> <button class="btn no sm" data-a="reject" data-id="${a.id}" ${isAdmin() ? '' : 'disabled'}>Reject</button>` : ''}</td></tr>`).join('')}</table>` : '<div class="empty">No containment actions (monitor-only or not planned yet)</div>'; }

// One recovery step: status, who does it, step-by-step guidance for the one that is ready, and the right buttons.
function taskRow(i, t, all) {
  const okDeps = (t.dependsOn || []).every((d) => ['done', 'skipped'].includes(all.find((x) => x.id === d)?.status)), ready = t.status === 'pending' && okDeps, c = canAct();
  const ic = { done: '✅', skipped: '⏭️', failed: '❌' }[t.status] || (ready ? '▶️' : '⬜');
  const who = t.gate ? '<span class="chip live">AI · needs your OK</span>' : t.owner === 'human' ? '<span class="chip sev-high">you</span>' : '<span class="chip live">AI</span>';
  const btn = !ready ? '' : t.gate ? `<button class="btn ok sm" data-a="task" data-id="${i.id}" data-t="${t.id}" ${c ? '' : 'disabled'}>✓ Allow</button> <button class="btn no sm" data-a="taskskip" data-id="${i.id}" data-t="${t.id}" ${c ? '' : 'disabled'}>✕ Disallow</button>` : t.owner === 'human' ? `${(t.links || []).map((l) => `<a class="btn pri sm" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a>`).join(' ')} ${t.checkable ? `<button class="btn ok sm" data-a="taskcheck" data-id="${i.id}" data-t="${t.id}" ${c ? '' : 'disabled'}>Check it</button> ` : ''}<button class="btn ${t.checkable ? 'ghost' : 'ok'} sm" data-a="task" data-id="${i.id}" data-t="${t.id}" ${c ? '' : 'disabled'}>✓ Done</button>${t.optional ? ` <button class="btn ghost sm" data-a="taskskip" data-id="${i.id}" data-t="${t.id}" ${c ? '' : 'disabled'}>Skip</button>` : ''}` : '<span class="mut">AI is on it…</span>';
  const how = ready && t.how && (t.owner === 'human' || t.gate) ? `<ol class="dim" style="margin:6px 0 4px 18px;font-size:12px">${t.how.map((x) => `<li>${esc(x)}</li>`).join('')}</ol>` : '';
  return `<div style="margin:8px 0;padding:8px;border:1px solid ${ready && (t.owner === 'human' || t.gate) ? 'rgba(255,179,71,.45)' : 'var(--line)'};border-radius:8px"><div class="between" style="gap:8px"><span>${ic} ${esc(t.title)} ${who}${t.critical ? ' <span class="chip sev-critical">critical</span>' : ''}${t.optional ? ' <span class="chip">optional</span>' : ''}${t.error ? `<div class="st-bad" style="font-size:11px">${esc(t.error)}</div>` : ''}${t.lastCheck && t.status === 'pending' ? `<div class="mut" style="font-size:11px">Last check: ${esc(t.lastCheck.detail || '')}</div>` : ''}</span><span style="white-space:nowrap">${btn}</span></div>${how}</div>`;
}
function recoveryBlock(i) {
  const r = i.recovery, done = r.tasks.filter((t) => ['done', 'skipped'].includes(t.status)).length;
  return `<div class="grid g2"><div class="card"><h2>Recovery readiness</h2>${r.readiness.map((x) => `<div class="note" style="border-color:${x.status === 'ready' ? 'var(--gr)' : 'var(--rd)'}"><b class="mono">${esc(x.host)}</b> <span class="chip ${x.status === 'ready' ? 't-automatic' : 't-restricted'}">${x.status}</span>${x.impacted ? ' <span class="chip sev-critical">impacted</span>' : ''}<div class="dim">${esc(x.note)}</div></div>`).join('') || '<div class="dim">No hosts need restoration</div>'}</div>
  <div class="card"><div class="between"><h2 style="margin:0">Recovery tasks</h2><span class="dim">${done}/${r.tasks.length}</span></div><div class="bar g" style="margin:8px 0"><i style="width:${r.tasks.length ? (done / r.tasks.length) * 100 : 0}%"></i></div>${r.tasks.map((t) => taskRow(i, t, r.tasks)).join('') || '<div class="dim">—</div>'}${r.tasks.some((t) => t.status === 'pending' && t.owner === 'human') ? `<button class="btn pri sm" style="margin-top:8px" data-a="taskall" data-id="${i.id}" ${canAct() ? '' : 'disabled'}>Complete all ready human tasks</button>` : ''}</div></div>
  <div class="card" style="margin-top:14px"><div class="between"><h2 style="margin:0">Post-recovery verification</h2>${i.verification ? `<span class="chip ${i.verification.passed ? 'live' : 'sev-high'}">${i.verification.passed ? 'PASSED' : i.verification.failed + ' FAILED'}</span>` : ''}</div>${i.verification ? i.verification.checks.map((c) => `<div style="margin:5px 0">${c.pass ? '<span class="st-ok">✓ PASS</span>' : '<span class="st-bad">✗ FAIL</span>'} ${esc(c.name)} <span class="mut">— ${esc(c.detail)}</span></div>`).join('') + `<button class="btn sm" style="margin-top:8px" data-a="verify" data-id="${i.id}" ${canAct() ? '' : 'disabled'}>Re-run verification</button>` : '<div class="dim">Runs after recovery tasks complete.</div>'}</div>`;
}
function intelTable(list) { return list.length ? `<table><tr><th>Type</th><th>Indicator</th><th>Verdict</th><th>Source</th><th>Detail</th></tr>${list.map((x) => `<tr><td>${esc(x.type)}</td><td class="mono">${esc(x.indicator.length > 40 ? x.indicator.slice(0, 18) + '…' + x.indicator.slice(-8) : x.indicator)}</td><td><span class="chip ${x.verdict === 'malicious' ? 'sev-critical' : x.verdict === 'suspicious' ? 'sev-medium' : x.verdict === 'unknown' ? '' : 't-automatic'}">${esc(x.verdict)}</span></td><td class="dim">${esc(x.source)}${x.live ? ' (live)' : ''}</td><td class="dim" style="font-size:12px">${esc(x.detail)} ${(x.tags || []).map((t) => `<span class="pill">${esc(t)}</span>`).join('')}</td></tr>`).join('')}</table>` : '<div class="empty">No indicators</div>'; }
function auditTable(rows) { return `<table><tr><th>#</th><th>Time</th><th>Actor</th><th>Action</th><th>Incident</th><th>Detail</th><th>Hash</th></tr>${rows.map((e) => `<tr><td class="mono mut">${e.seq}</td><td class="mono dim">${fmtT(e.ts)}</td><td><b>${esc(e.actor)}</b></td><td class="mono">${esc(e.action)}</td><td class="mono">${esc(e.incidentId || '')}</td><td class="dim" style="font-size:11.5px;max-width:420px;word-break:break-word">${esc(JSON.stringify(e.detail).slice(0, 200))}</td><td class="mono mut">${e.hash.slice(0, 8)}</td></tr>`).join('')}</table>`; }

// ---------- interaction (delegated) ----------

const PROD = () => S.settings?.mode === 'production';
U.admin = { users: [], keys: [], loaded: false };
async function loadAdmin() { if (!isAdmin() || U.admin.loaded) return; U.admin.loaded = true; try { U.admin.users = await api('/api/users'); U.admin.keys = (await api('/api/keys')).keys; S.suppressions = await api('/api/suppressions'); } catch {} if (route().page === 'settings') render(); }
const fld = (n, l, extra = '') => `<label class="dim" style="font-size:11px">${l}<input name="${n}" ${extra} style="width:100%"></label>`;
function adminCards() {
  if (route().page === 'settings') setTimeout(loadAdmin, 0);
  const conn = S.connectors || {};
  const acct = `<div class="card"><h2>My account</h2><form data-f="pw" class="grid g2" style="gap:8px">${fld('current', 'Current password', 'type=password autocomplete=current-password')}${fld('next', 'New password (12+ chars, letters + digits)', 'type=password autocomplete=new-password')}</form><button class="btn" data-a="submitform" data-form="pw">Change password</button> <button class="btn" data-a="totpstart">Set up authenticator (2FA)</button><div id="totpres"></div></div>`;
  if (!isAdmin()) return `<div class="grid g2" style="margin-top:14px">${acct}${supCard()}</div>`;
  const users = `<div class="card"><h2>Users</h2><table><tr><th>User</th><th>Role</th><th>2FA</th><th>Last login</th><th></th></tr>${U.admin.users.map((u) => `<tr><td>${esc(u.username)}${u.disabled ? ' <span class="chip sev-high">disabled</span>' : ''}</td><td><select data-a="userrole" data-id="${esc(u.username)}">${['viewer', 'analyst', 'admin'].map((r) => `<option ${r === u.role ? 'selected' : ''}>${r}</option>`).join('')}</select></td><td>${u.totp ? '✓' : '—'}</td><td class="mut">${u.lastLogin ? fmtDT(u.lastLogin) : 'never'}</td><td><button class="btn ghost" data-a="userdis" data-id="${esc(u.username)}" data-v="${u.disabled ? 0 : 1}">${u.disabled ? 'Enable' : 'Disable'}</button> <button class="btn no" data-a="userdel" data-id="${esc(u.username)}">Delete</button></td></tr>`).join('')}</table>
    <form data-f="newuser" class="grid g3" style="gap:8px;margin-top:10px">${fld('username', 'Username')}${fld('password', 'Initial password (12+)', 'type=password')}<label class="dim" style="font-size:11px">Role<select name="role" style="width:100%"><option>analyst</option><option>viewer</option><option>admin</option></select></label><button class="btn pri">Add user</button></form></div>`;
  const keys = `<div class="card"><h2>Ingest keys <span class="chip">one per log source</span> <button class="btn ghost sm" data-a="rotall" style="float:right">🔑 Rotate all</button></h2><table><tr><th>Name</th><th>Format</th><th>Last used</th><th></th></tr>${U.admin.keys.map((k) => `<tr><td>${esc(k.name)}${k.disabled ? ' <span class="chip sev-high">revoked</span>' : ''}</td><td class="mono">${esc(k.format)}</td><td class="mut">${k.lastUsed ? fmtDT(k.lastUsed) : 'never'}</td><td>${k.disabled ? '' : `<button class="btn ghost" data-a="keyrot" data-id="${esc(k.id)}" title="Create a new key and disable the old one">🔑 Rotate</button> <button class="btn no" data-a="keyrev" data-id="${esc(k.id)}">Revoke</button>`}</td></tr>`).join('') || '<tr><td colspan=4 class="dim">No keys yet</td></tr>'}</table>
    <form data-f="newkey" class="grid g3" style="gap:8px;margin-top:10px">${fld('name', 'Source name (e.g. okta-prod)')}<label class="dim" style="font-size:11px">Format<select name="format" style="width:100%">${['generic', 'okta', 'entra', 'cloudtrail', 'windows', 'syslog', 'cef', 'vercel', 'vercel-webhook', 'render', 'render-webhook', 'heroku', 'netlify', 'railway', 'cloudflare', 'github', 'nginx'].map((f) => `<option>${f}</option>`).join('')}</select></label><button class="btn pri">Create key</button></form><div id="newkey"></div></div>`;
  const assets = `<div class="card"><h2>Asset inventory</h2><div class="dim" style="font-size:12px">Tell PHOENIX which assets are production and how critical they are. <b>Unknown assets fail safe: every action on them needs approval.</b></div>
    <form data-f="asset" class="grid g3" style="gap:8px;margin-top:8px"><label class="dim" style="font-size:11px">Kind<select name="kind" style="width:100%"><option>host</option><option>user</option><option>resource</option></select></label>${fld('name', 'Name (host / user / bucket)')}<label class="dim" style="font-size:11px">Environment<select name="env" style="width:100%"><option>production</option><option>sandbox</option></select></label><label class="dim" style="font-size:11px">Criticality<select name="criticality" style="width:100%"><option>medium</option><option>high</option><option>critical</option><option>low</option></select></label>${fld('owner', 'Owner')}<button class="btn pri">Save asset</button></form>
    <form data-f="backup" class="grid g3" style="gap:8px;margin-top:8px">${fld('host', 'Host')}${fld('id', 'Backup ID')}${fld('ts', 'Taken at (ISO date)', 'placeholder=2026-11-01T02:00:00Z')}<label class="dim" style="font-size:11px"><input type="checkbox" name="verified" style="width:auto"> verified restore test</label><label class="dim" style="font-size:11px"><input type="checkbox" name="immutable" style="width:auto"> immutable</label><button class="btn">Record backup</button></form></div>`;
  const ops = `<div class="card"><h2>Containment connectors</h2>${Object.entries(conn).map(([k, v]) => `<div class="between" style="margin:6px 0"><span>${esc(k)}</span><span class="chip ${/LIVE/.test(v) ? 'live' : /DRY/.test(v) ? 'sev-medium' : 'sim'}">${esc(v)}</span></div>`).join('')}<div class="note">Set in <span class="mono">.env</span>. Live connectors start in <b>DRY-RUN</b>: nothing is changed until <span class="mono">PHOENIX_CONNECTOR_DRYRUN=off</span>. Actions are only marked done when the provider confirms them.</div><button class="btn" data-a="backupnow">Back up database now</button></div>`;
  return `<div class="grid g2" style="margin-top:14px">${users}${keys}</div><div class="grid g2" style="margin-top:14px">${assets}<div>${ops}${supCard()}</div></div><div class="grid g2" style="margin-top:14px">${acct}</div>`;
}

function showSecret(title, secret) {
  const d = document.createElement('div'); d.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;z-index:9999';
  d.innerHTML = `<div class="card" style="max-width:560px;width:92%"><h2>${esc(title)}</h2><p class="dim">Copy it now. It is shown only once.</p><pre class="md" style="user-select:all;word-break:break-all;white-space:pre-wrap">${esc(secret)}</pre><div class="row"><button class="btn pri" id="sc-copy">Copy</button><button class="btn ghost" id="sc-close">Close</button></div></div>`;
  document.body.appendChild(d); d.querySelector('#sc-close').onclick = () => d.remove(); d.querySelector('#sc-copy').onclick = () => { try { navigator.clipboard.writeText(secret); toast('Copied'); } catch { /* manual copy */ } };
}
// ---------- Autonomy: mode selector, protected entities, and the AI's active blocks (with Unblock) ----------
const UNDOABLE = ['block_ip', 'restrict_resource', 'disable_account', 'isolate_host'];
function autonomyCard() {
  const A = S.autonomy || { mode: 'watch', modes: {}, budget: {}, protected: [] }, adm = isAdmin();
  const tiles = Object.entries(A.modes || {}).map(([k, m]) => `<div class="card scn ${A.mode === k ? 'on' : ''}" ${adm ? `data-a="setmode" data-id="${k}"` : ''} style="cursor:${adm ? 'pointer' : 'default'};${A.mode === k ? 'outline:2px solid var(--accent,#ff6a1a)' : ''}"><b>${esc(m.label)}</b>${A.mode === k ? ' <span class="chip live">active</span>' : ''}<div class="dim" style="font-size:12px;margin-top:4px">${esc(m.blurb)}</div></div>`).join('');
  const P = A.protected || [];
  return `<div class="card" style="margin-bottom:14px"><h2>AI autonomy ${adm ? '' : '<span class="chip">admin can change</span>'}</h2>
    <div class="grid g3">${tiles}</div>
    <div class="note" style="margin-top:8px">In <b>every</b> mode: destructive actions (delete data, shut down or wipe hosts, change security controls) are never executed. Protected entities and internal IPs always need a human. Circuit breaker: <b>${A.budget?.used ?? 0}/${A.budget?.max ?? 0}</b> automatic actions this hour${A.budget?.tripped ? ' <span class="chip sev-high">tripped — asking humans</span>' : ''}.</div>
    <h3 style="margin:12px 0 4px">Protected (never auto-blocked)</h3>${P.map((x) => `<div class="note"><b>${esc(x.kind)}</b> <span class="mono">${esc(x.value)}</span> <span class="mut">— ${esc(x.reason)}${x.expiresAt ? ' · until ' + fmtDT(x.expiresAt) : ' · permanent'}</span> ${adm ? `<button class="btn ghost" data-a="protdel" data-id="${esc(x.id)}">Remove</button>` : ''}</div>`).join('') || '<div class="dim">None yet. Internal IPs (10.x, 192.168.x) are always protected.</div>'}
    ${adm ? `<form data-f="protect" class="grid g3" style="gap:8px;margin-top:8px"><label class="dim" style="font-size:11px">Kind<select name="kind" style="width:100%"><option>user</option><option>ip</option><option>host</option><option>resource</option></select></label>${fld('value', 'Value (e.g. ceo@acme.com)')}${fld('reason', 'Reason')}<button class="btn pri">Protect</button></form>` : ''}</div>`;
}
function containCard() {
  const acts = [...allDetails().flatMap((i) => i.containment.map((a) => ({ ...a, inc: i.id }))), ...(S.manual || []).map((a) => ({ ...a, inc: 'manual', rationale: a.reason, approvedBy: a.requestedBy }))].filter((a) => a.status === 'executed' && UNDOABLE.includes(a.type));
  const can = canAct();
  return `<div class="card" style="margin-bottom:14px"><h2>Active blocks <span class="chip">${acts.length}</span> <span class="dim" style="font-size:12px">— things the AI (or you) switched off. Unblock any of them.</span></h2>${acts.length ? `<table><tr><th>What</th><th>Why</th><th>By</th><th>Lifts</th><th></th></tr>${acts.map((a) => `<tr><td>${esc(a.description)}<div class="mut mono" style="font-size:11px">${esc(a.inc)}</div></td><td class="dim">${esc(a.rationale || a.reason || '')}</td><td>${a.aiAuto ? '<span class="chip live">AI</span>' : esc(a.approvedBy || '')}</td><td class="mut">${a.expiresAt ? 'auto ' + fmtDT(a.expiresAt) : 'when a human lifts it'}</td><td style="white-space:nowrap">${can ? `<button class="btn ok" data-a="undo" data-id="${esc(a.id)}">Unblock</button> ${isAdmin() ? `<button class="btn ghost" data-a="undo" data-trust="1" data-id="${esc(a.id)}" title="Unblock and never let the AI block this again">Unblock &amp; trust</button>` : ''}` : ''}</td></tr>`).join('')}</table>` : '<div class="empty">Nothing is blocked right now</div>'}${can ? `<form data-f="manualblock" class="row" style="gap:8px;margin-top:10px"><input name="ip" placeholder="Block an IP address now (e.g. 203.0.113.9)" style="flex:1" pattern="[0-9a-fA-F:.]+" required><button class="btn no">Block now</button></form>` : ''}</div>`;
}

// ---------- Pull collectors: connect with a read-only API token, no drains/webhooks ----------
async function loadCol() { const K = U.col ||= { platform: 'github', data: null, busy: false }; try { K.data = await api('/api/collectors'); render(); } catch { /* not admin */ } }
function collectorCard() {
  const K = U.col ||= { platform: 'github', data: null }; if (!K.data) { setTimeout(loadCol, 0); return ''; }
  const cat = K.data.catalog, sp = cat[K.platform] || cat.github, chip = (st) => `<span class="chip ${st === 'ok' ? 'live' : st === 'pending' ? 'sim' : 'sev-high'}">${esc(st === 'auth_failed' ? 'token rejected' : st)}</span>`;
  return `<div class="card" style="margin:14px 0;border-color:var(--accent,#ff6a1a)"><h2>Easiest: connect with an API token <span class="chip live">no drain, no webhook</span></h2>
    <p class="dim">PHOENIX X reads your platform's own logs and events using a <b>read-only token you create</b>, every couple of minutes. Nothing to configure on the platform, no paid log-drain plan. The token is stored encrypted and can be removed any time. It is only used to read.</p>
    <div class="row" style="gap:8px;flex-wrap:wrap;margin:8px 0">${Object.entries(cat).map(([k, v]) => `<button class="btn ${k === K.platform ? 'pri' : 'ghost'}" data-a="colplat" data-id="${k}">${esc(v.label)}</button>`).join('')}</div>
    <form data-f="newcol" class="grid g3" style="gap:8px"><input type="hidden" name="platform" value="${esc(K.platform)}">${fld('name', 'Name (optional)')}${sp.fields.map((f) => fld(f.k, f.label)).join('')}<label class="dim" style="font-size:11px">API token<input name="token" type="password" autocomplete="off" required style="width:100%"></label><label class="dim" style="font-size:11px">Check every (seconds)<input name="intervalSec" type="number" min="30" max="3600" value="120" style="width:100%"></label><button class="btn pri">Test &amp; connect</button></form>
    <div class="mut" style="font-size:12px;margin-top:6px">${sp.tokenUrl ? `<a class="btn ghost sm" href="${esc(sp.tokenUrl)}" target="_blank" rel="noopener noreferrer">Create a token ↗</a> ` : ''}${esc(sp.scopes)} ${K.platform === 'vercel' ? 'Vercel request logs have no pull API: use a Log Drain or the SDK for those; deployments are pulled here.' : ''}</div><div id="colmsg"></div>
    ${K.data.collectors.length ? `<table style="margin-top:10px"><tr><th>Connection</th><th>Status</th><th>Last check</th><th>Events</th><th></th></tr>${K.data.collectors.map((c) => `<tr><td><b>${esc(c.name)}</b> <span class="mut">${esc(Object.values(c.config).join(' · '))}</span></td><td>${chip(c.enabled ? c.status : 'paused')}${c.error ? `<div class="mut" style="font-size:11px">${esc(c.error)}</div>` : ''}</td><td class="mut">${c.lastRun ? fmtDT(c.lastRun) : '—'}</td><td>${c.totalEvents}</td><td style="white-space:nowrap"><button class="btn ghost" data-a="colrun" data-id="${esc(c.id)}">Check now</button> <button class="btn ghost" data-a="coltok" data-id="${esc(c.id)}">🔑 New token</button> <button class="btn ghost" data-a="colpause" data-id="${esc(c.id)}" data-on="${c.enabled ? '' : '1'}">${c.enabled ? 'Pause' : 'Resume'}</button> ${['vercel', 'render', 'netlify', 'heroku'].includes(c.platform) ? `<button class="btn ghost" data-a="colwrite" data-id="${esc(c.id)}" data-on="${c.writeEnabled ? '' : '1'}" title="Lets PHOENIX X redeploy/restart this service after an admin approves a recovery plan">${c.writeEnabled ? '✍️ Write on' : 'Allow redeploy'}</button> ` : ''}<button class="btn ghost" data-a="coldel" data-id="${esc(c.id)}">Remove</button></td></tr>`).join('')}</table>` : ''}</div>`;
}
function supCard() {
  const L = S.suppressions || [];
  return `<div class="card" style="margin-top:14px"><h2>Suppressions (known-good)</h2>${L.map((x) => `<div class="note"><b>${esc(x.rule)}</b> ${esc([x.user, x.ip, x.host].filter(Boolean).join(' · ') || 'any')} <span class="mut">— ${esc(x.reason)}${x.expires_at ? ' · expires ' + fmtDT(x.expires_at) : ''} · by ${esc(x.created_by)}</span> ${isAdmin() ? `<button class="btn ghost" data-a="supdel" data-id="${esc(x.id)}">Remove</button>` : ''}</div>`).join('') || '<div class="dim">None. Suppressing a rule needs a reason and is audited.</div>'}
  ${isAdmin() ? `<form data-f="newsup" class="grid g3" style="gap:8px;margin-top:8px">${fld('rule', 'Rule (e.g. R-BRUTE)')}${fld('user', 'User (optional)')}${fld('ip', 'IP (optional)')}${fld('host', 'Host (optional)')}${fld('reason', 'Reason (required)')}${fld('expiresInHours', 'Expires in hours', 'type=number')}<button class="btn pri">Add suppression</button></form>` : ''}</div>`;
}

async function loadConn(force) { const C = U.conn ||= { platform: 'vercel', method: null, created: null, cat: null, keys: [] }; try { if (!C.cat) { C.cat = await api('/api/platforms'); render(); } C.keys = (await api('/api/keys')).keys; } catch {} if (route().page === 'connect') { clearTimeout(U.connT); U.connT = setTimeout(() => { if (route().page === 'connect') loadConn().then(() => { const el = document.activeElement; if (!(el && ['INPUT', 'TEXTAREA', 'SELECT'].includes(el.tagName))) render(); }); }, 4000); } }
function bind() {}
document.addEventListener('click', async (ev) => {
  const el = ev.target.closest('[data-a]'); if (!el) { const g = ev.target.closest('[data-node]'); if (g) { U.node = g.dataset.node; render(); } return; }
  const a = el.dataset.a, id = el.dataset.id;
  if (a === 'msg') return el.classList.toggle('open');
  if (a === 'node') { U.node = id; return render(); }
  if (a === 'tab') { U.tab = id; return render(); }
  if (a === 'launch') { if (!canAct()) return; if (id === 'signature') location.hash = '#/command'; await act(() => api(`/api/scenarios/${id}/launch`, 'POST', { autopilot: id === 'signature' ? !!S.settings.autopilot : S.settings.autopilot }), 'Scenario launched — watch the agents work'); }
  if (a === 'approve' || a === 'reject') { await act(() => api(`/api/actions/${id}/${a}`, 'POST', { comment: 'via console' }), a === 'approve' ? 'Approved — executing' : 'Rejected'); S.approvals = S.approvals.filter((x) => x.action.id !== id); render(); }
  if (a === 'task') await act(() => api(`/api/incidents/${id}/tasks/${el.dataset.t}/complete`, 'POST', {}));
  if (a === 'taskall') await act(() => api(`/api/incidents/${id}/tasks/complete-all`, 'POST', {}), 'Tasks completed');
  if (a === 'verify') await act(() => api(`/api/incidents/${id}/verify`, 'POST', {}), 'Verification re-run');
  if (a === 'note') { const t = $('#note').value.trim(); if (t) { await act(() => api(`/api/incidents/${U.detailId}/notes`, 'POST', { text: t })); refreshDetail(); } }
  if (a === 'assign') { const v = $('#analyst').value.trim(); if (v) { await act(() => api(`/api/incidents/${U.detailId}/assign`, 'POST', { analyst: v }), 'Assigned'); refreshDetail(); } }
  if (a === 'dlmd') dl(`/api/incidents/${U.detailId}/report.md`, `${U.detailId}-report.md`);
  if (a === 'dljson') dl(`/api/incidents/${U.detailId}/report.json`, `${U.detailId}-evidence-bundle.json`);
  if (a === 'reset') { if (confirm('Reset simulated environment, incidents and events?')) await act(() => api('/api/reset', 'POST', {}), 'Environment reset'); }
  if (a === 'resume') { if (confirm('Re-run the response workflow from triage? Containment will again require approval.')) await act(() => api(`/api/incidents/${id}/resume`, 'POST', {}), 'Workflow resumed'); refreshDetail(id); }
  if (a === 'connplat') { U.conn.platform = id; U.conn.method = null; render(); return; }
  if (a === 'connmethod') { U.conn.method = id; render(); return; }
  if (a === 'conntest') { await act(() => api(`/api/keys/${id}/test`, 'POST', {}), 'Test event sent'); loadConn(); return; }
  if (a === 'submitform') { const f = document.querySelector(`[data-f="${el.dataset.form}"]`); f.requestSubmit(); return; }
  if (a === 'userdis') { await act(() => api(`/api/users/${id}/update`, 'POST', { disabled: el.dataset.v === '1' }), 'Updated'); U.admin.loaded = false; loadAdmin(); }
  if (a === 'userdel') { if (confirm(`Delete user ${id}?`)) { await act(() => api(`/api/users/${id}/delete`, 'POST', {}), 'User deleted'); U.admin.loaded = false; loadAdmin(); } }
  if (a === 'keyrev') { if (confirm('Revoke this key? The log source will stop working.')) { await act(() => api(`/api/keys/${id}/revoke`, 'POST', {}), 'Key revoked'); U.admin.loaded = false; loadAdmin(); if (route().page === 'connect') loadConn(); } }
  if (a === 'taskcheck') { const r = await act(() => api(`/api/incidents/${id}/tasks/${el.dataset.t}/check`, 'POST', {})); if (r) { toast(esc(r.done ? 'Verified. Moving on.' : r.detail || 'Not done yet')); U.stamp = {}; setTimeout(render, 500); } return; }
  if (a === 'rotall') { if (!confirm('Rotate ALL ingest keys? Every connected platform stops sending until you paste its new key.')) return; const r = await act(() => api('/api/keys/rotate-all', 'POST', {})); if (r) { showSecret(`${r.keys.length} new key(s)`, r.keys.map((k) => `${k.name}: ${k.key}`).join('\n')); U.admin.loaded = false; loadAdmin?.(); loadConn?.(true); } return; }
  if (a === 'coltok') { const t = prompt('Paste the NEW read-only API token (stored encrypted):'); if (t) { await act(() => api(`/api/collectors/${id}/token`, 'POST', { token: t }), 'Token replaced'); loadCol(); } return; }
  if (a === 'taskskip') { await act(() => api(`/api/incidents/${id}/tasks/${el.dataset.t}/skip`, 'POST', {}), 'Skipped'); U.stamp = {}; setTimeout(render, 500); return; }
  if (a === 'keyrot') { if (!confirm('Rotate this key? The old key stops working immediately; you must paste the new one into the platform.')) return; const r = await act(() => api(`/api/keys/${id}/rotate`, 'POST', {})); if (r) { showSecret('New key for ' + r.name, r.key); U.admin.loaded = false; loadAdmin?.(); loadConn?.(true); } return; }
  if (a === 'allowall') { for (const x of S.approvals.slice()) await act(() => api(`/api/actions/${x.action.id}/approve`, 'POST', { comment: 'allow all' })); S.approvals = []; await loadState(); return; }
  if (a === 'colplat') { U.col.platform = id; render(); return; }
  if (a === 'colrun') { const r = await act(() => api(`/api/collectors/${id}/run`, 'POST', {}), 'Checked'); if (r) toast(esc(r.status === 'ok' ? `OK · ${r.events} new event(s)` : (r.error || r.status))); loadCol(); return; }
  if (a === 'colwrite') { if (el.dataset.on && !confirm('Allow PHOENIX X to redeploy/restart this service? It will only do so after an admin approves a recovery plan. Use a token that is allowed to deploy.')) return; await act(() => api(`/api/collectors/${id}/write`, 'POST', { enabled: !!el.dataset.on }), 'Updated'); loadCol(); return; }
  if (a === 'colpause') { await act(() => api(`/api/collectors/${id}/enable`, 'POST', { enabled: !!el.dataset.on }), 'Updated'); loadCol(); return; }
  if (a === 'coldel') { if (confirm('Remove this connection and its stored token?')) { await act(() => api(`/api/collectors/${id}/remove`, 'POST', {}), 'Removed'); loadCol(); } return; }
  if (a === 'setmode') { const r = await act(() => api('/api/autonomy', 'POST', { mode: id }), 'Autonomy set to ' + id); if (r) { S.autonomy = r; await loadState(); } return; }
  if (a === 'protdel') { await act(() => api(`/api/protected/${id}/remove`, 'POST', {}), 'Removed'); await loadState(); return; }
  if (a === 'undo') { const trust = !!el.dataset.trust; const r = await act(() => api(`/api/actions/${id}/undo`, 'POST', { trust, reason: trust ? 'trusted by admin' : 'unblocked by user' }), trust ? 'Unblocked and trusted' : 'Unblocked'); if (r) { U.stamp = {}; await loadState(); U.detailId && refreshDetail(); setTimeout(render, 700); } return; }
  if (a === 'supdel') { await act(() => api(`/api/suppressions/${id}/remove`, 'POST', {}), 'Suppression removed'); S.suppressions = await api('/api/suppressions'); render(); }
  if (a === 'backupnow') { const r = await act(() => api('/api/admin/backup', 'POST', {})); if (r) toast('Backup written: <span class="mono">' + esc(r.file) + '</span>', 'ok'); }
  if (a === 'totpstart') { const r = await act(() => api('/api/auth/totp/begin', 'POST', {})); if (r) $('#totpres').innerHTML = `<div class="note">Add this secret to your authenticator app:<pre class="md" style="user-select:all">${esc(r.secret)}</pre><form data-f="totpconfirm" class="row"><input name="code" placeholder="6-digit code" maxlength="6"><button class="btn pri">Confirm</button></form></div>`; }
  if (a === 'verifychain') { const r = await act(() => api('/api/audit/verify')); if (r) $('#chainres').innerHTML = r.ok ? `<span class="st-ok">✓ chain intact · ${r.length} entries · head ${r.head.slice(0, 12)}</span>` : `<span class="st-bad">✗ BROKEN at entry ${r.brokenAt}</span>`; }
});
document.addEventListener('change', async (ev) => {
  const el = ev.target.closest('[data-a]'); if (!el) return; const a = el.dataset.a;
  if (a === 'status') { await act(() => api(`/api/incidents/${U.detailId}/status`, 'POST', { status: el.value }), 'Status updated'); refreshDetail(); }
  if (a === 'graphpick') { U.graphInc = el.value; U.detail = null; U.node = null; render(); }
  if (a === 'feedfilter') { U.feedFilter = el.value; render(); }
  if (a === 'pause') U.feedPaused = el.checked;
  if (a === 'autopilot') { await act(() => api('/api/settings', 'POST', { autopilot: el.checked })); S.settings.autopilot = el.checked; }
  if (a === 'setting') { const r = await act(() => api('/api/settings', 'POST', { [el.dataset.id]: el.checked })); if (r) S.settings = r; render(); }
  if (a === 'userrole') { await act(() => api(`/api/users/${el.dataset.id}/update`, 'POST', { role: el.value }), 'Role updated'); U.admin.loaded = false; loadAdmin(); }
  if (a === 'apptimeout') { const r = await act(() => api('/api/settings', 'POST', { approvalTimeoutMin: +el.value }), 'Saved'); if (r) S.settings = r; }
  if (a === 'pace') { const r = await act(() => api('/api/settings', 'POST', { paceMs: +el.value })); if (r) S.settings = r; render(); }
});
document.addEventListener('input', (ev) => { if (ev.target.dataset?.a === 'auditfilter') { U.auditFilter = ev.target.value; clearTimeout(U.af); U.af = setTimeout(() => { const p = $('#page'); const pos = ev.target.selectionStart; ev.target.blur(); render(); const n = $('[data-a=auditfilter]'); if (n) { n.focus(); n.setSelectionRange(pos, pos); } }, 250); } });
document.addEventListener('submit', async (ev) => {
  const f = ev.target.dataset?.f; if (!f) return; ev.preventDefault(); const d = Object.fromEntries(new FormData(ev.target));
  const bool = (v) => v === 'on';
  if (f === 'pw') { const r = await act(() => api('/api/auth/password', 'POST', d), 'Password changed — sign in again'); if (r) setTimeout(() => location.reload(), 1200); }
  if (f === 'totpconfirm') { const r = await act(() => api('/api/auth/totp/confirm', 'POST', d), 'Two-factor enabled'); if (r) $('#totpres').innerHTML = '<span class="st-ok">✓ enabled</span>'; }
  if (f === 'newuser') { const r = await act(() => api('/api/users', 'POST', d), 'User created'); if (r) { U.admin.loaded = false; ev.target.reset(); loadAdmin(); } }
  if (f === 'newkey') { const r = await act(() => api('/api/keys', 'POST', d)); if (r) { $('#newkey').innerHTML = `<div class="note"><b>Copy this key now — it is shown once:</b><pre class="md" style="user-select:all">${esc(r.key)}</pre></div>`; U.admin.loaded = false; loadAdmin(); } }
  if (f === 'newcol') { const { platform, name, token, intervalSec, ...config } = d; $('#colmsg').innerHTML = '<div class="note">Testing the token…</div>'; try { const r = await api('/api/collectors', 'POST', { platform, name, token, intervalSec: +intervalSec, config }); ev.target.reset(); $('#colmsg').innerHTML = `<div class="note"><span class="st-ok">✓ Connected.</span> Existing items were recorded as a baseline; only NEW activity will raise alerts.${(r.notes || []).map((n) => `<div class="mut">${esc(n)}</div>`).join('')}</div>`; loadCol(); } catch (e) { $('#colmsg').innerHTML = `<div class="note" style="border-color:#ff5c5c">✗ ${esc(e.message)}</div>`; } return; }
  if (f === 'manualblock') { const r = await act(() => api('/api/manual', 'POST', { type: 'block_ip', target: { ip: d.ip }, reason: 'blocked from console' }), 'Blocked'); if (r) { ev.target.reset(); U.stamp = {}; await loadState(); setTimeout(render, 600); } return; }
  if (f === 'protect') { const r = await act(() => api('/api/protected', 'POST', d), 'Protected'); if (r) { ev.target.reset(); await loadState(); } return; }
  if (f === 'newsup') { const body = { ...d, expiresInHours: d.expiresInHours ? +d.expiresInHours : undefined }; for (const k of ['user', 'ip', 'host']) if (!body[k]) delete body[k]; const r = await act(() => api('/api/suppressions', 'POST', body), 'Suppression added'); if (r) { S.suppressions = await api('/api/suppressions'); ev.target.reset(); render(); } }
  if (f === 'asset') { const r = await act(() => api(`/api/assets/${d.kind}/${encodeURIComponent(d.name)}`, 'POST', { env: d.env, criticality: d.criticality, owner: d.owner || undefined }), 'Asset saved'); if (r) ev.target.reset(); }
  if (f === 'backup') { const r = await act(() => api('/api/assets/backups', 'POST', { host: d.host, id: d.id, ts: d.ts, verified: bool(d.verified), immutable: bool(d.immutable) }), 'Backup recorded'); if (r) ev.target.reset(); }
  if (f === 'newconn') { const C = U.conn, pl = C.cat.find((x) => x.id === C.platform), m = pl.methods.find((x) => x.id === C.method) || pl.methods[0]; const body = { name: d.name, format: m.format, signingSecret: d.signingSecret || undefined, verifyToken: d.verifyToken || undefined }; const r = await act(() => api('/api/keys', 'POST', body), 'Connection created'); if (r) { C.created = { ...r, method: pl.id + '/' + m.id }; loadConn(); render(); } }
  if (f === 'lookup') { const r = await act(() => api('/api/intel/lookup', 'POST', d)); if (r) $('#lookres').innerHTML = intelTable([r]); }
  if (f === 'kb') { const r = await act(() => api('/api/kb?q=' + encodeURIComponent(d.q))); if (r) $('#kbres').innerHTML = r.map((x) => `<div class="note"><b>${esc(x.id)} · ${esc(x.title)}</b> <span class="mut">score ${x.score}</span><div class="dim">${esc(x.text.slice(0, 260))}…</div></div>`).join('') || '<div class="dim">No matches</div>'; }
  if (f === 'policy') { let target; try { target = JSON.parse(d.target); } catch { return toast('Target must be JSON', 'bad'); } const r = await act(() => api('/api/guardian/execute', 'POST', { type: d.type, target, approve: !!d.approve })); if (r) $('#polres').textContent = JSON.stringify(r, null, 2); }
});

async function boot() {
  $('#app').classList.remove('hidden'); U.admin.loaded = false; $('#whoami').innerHTML = `Signed in: <b>${esc(ME.user)}</b> <span class="chip">${esc(ME.role)}</span>`;
  try { await loadState(); S.audit = await api('/api/audit?limit=500'); } catch (e) { return; }
  const mb = $('#modebadge'); if (mb) { mb.className = 'chip ' + (PROD() ? 'live' : 'sim'); mb.textContent = PROD() ? 'PRODUCTION' : 'SIMULATED ENVIRONMENT'; }
  connectWS(); render();
}
$('#logout').onclick = async () => { try { await api('/api/auth/logout', 'POST', {}); } catch {} location.reload(); };
setInterval(() => { $('#clock').textContent = new Date().toLocaleTimeString([], { hour12: false }); }, 1000);
(async () => { try { const me = await api('/api/auth/me'); ME = { user: me.user, role: me.role }; CSRF = me.csrf; if (me.totpEnrolRequired) return showEnrol(); boot(); } catch { showLogin(); } })();
